"""Triage customer support tickets with SubQ Snap (subq-snap-preview, POST https://api.subq.ai/v1/systemone).

For each ticket, one request asks three independent questions:
  urgent   (noul)   probability the ticket needs a response within the hour
  team     (choice) billing / engineering / sales / other
  severity (score)  3 ordered levels: 0 = low, 1 = medium, 2 = high

Code turns the probabilities into a decision and flags uncertain tickets for a human.
The thresholds below are starting points: calibrate them on tickets you have already labelled.

Input:  a .jsonl file with {"id": ..., "text": ...} per line, or a plain text file with one ticket per line.
Output: one JSON object per ticket on stdout (raw probabilities included so thresholds can change later).

Usage:
    export SUBQ_API_KEY=...        # never put the key in this file
    python3 triage.py tickets.jsonl > triaged.jsonl
"""

from __future__ import annotations

import argparse
import http.client
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Review thresholds (placeholders until calibrated on labelled tickets).
URGENT_YES = 0.70          # urgent if p(urgent) >= this
URGENT_NO = 0.30           # not urgent if p(urgent) <= this; in between -> human review
MIN_TEAM_CONFIDENCE = 0.60
MIN_SEVERITY_CONFIDENCE = 0.50

SEVERITY_LABELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Does this customer support ticket need a response within the hour?",
        "criteria": {
            "true": "Outage, data loss, security incident, account lockout, or a payment that is blocked or charged wrongly right now",
            "false": "Questions, feature requests, minor bugs and anything that can wait until the next business day",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Which team should own this customer support ticket?",
        "criteria": {
            "billing": "Charges, invoices, refunds, payment methods, subscription billing",
            "engineering": "Bugs, crashes, errors, outages, performance, integrations and API problems",
            "sales": "Pricing questions, plan upgrades, new purchases, quotes, demos",
            "other": "Anything that fits none of the above, such as general feedback or account administration",
        },
    },
    "severity": {
        "type": "score",
        "instructions": "How badly is the customer affected by the problem described in this ticket?",
        "criteria": [
            "Low: a question, a cosmetic issue or a request; nothing is broken for the customer",
            "Medium: something is broken or wrong but the customer can still work, e.g. with a workaround",
            "High: the customer cannot use the product or is losing money or data",
        ],
    },
}


class SnapError(Exception):
    def __init__(self, status: int | None, error_type: str, message: str) -> None:
        super().__init__(f"{status} {error_type}: {message}")
        self.status = status
        self.error_type = error_type


class FatalError(SnapError):
    """Key, credits or model access problem: no further ticket can succeed."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # Following a redirect could resend the Authorization header to another host.
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        return None


_OPENER = urllib.request.build_opener(_NoRedirect)


def _error_detail(e: urllib.error.HTTPError) -> dict:
    try:
        payload = json.load(e)
    except ValueError:
        return {}
    detail = payload.get("detail") if isinstance(payload, dict) else None
    return detail if isinstance(detail, dict) else {"message": str(payload)[:200]}


def decide(key: str, state, questions: dict, *, attempts: int = 5, timeout_s: float = 60.0) -> dict:
    """One Decisions API call, retrying 429 / 5xx / network failures with exponential backoff and full jitter."""
    data = json.dumps({"model": MODEL, "state": state, "questions": questions}).encode()
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    for attempt in range(attempts):
        last = attempt == attempts - 1
        try:
            request = urllib.request.Request(URL, data=data, headers=headers, method="POST")
            with _OPENER.open(request, timeout=timeout_s) as response:
                return json.load(response)
        except urllib.error.HTTPError as e:
            detail = _error_detail(e)
            error_type, message = detail.get("error_type", "http_error"), detail.get("message", "")
            if e.code in (401, 402, 403):
                raise FatalError(e.code, error_type, message) from e
            if not (e.code == 429 or e.code >= 500) or last:
                raise SnapError(e.code, error_type, message) from e
            retry_after = e.headers.get("Retry-After") if e.headers else None
        except (OSError, http.client.HTTPException, ValueError) as e:
            # Timeouts, resets, truncated or non-JSON bodies. Retrying is safe: a decision has no side effects.
            if last:
                raise SnapError(None, "network", f"{type(e).__name__}: {e}") from e
            retry_after = None
        delay = random.uniform(0, min(30.0, 2.0**attempt))
        if retry_after and retry_after.isdigit():
            delay = max(delay, float(retry_after))
        time.sleep(delay)
    raise AssertionError("unreachable")


def triage(ticket_id, text: str, answers: dict) -> dict:
    p_urgent = answers["urgent"]["noul"]
    team = answers["team"]
    sev = answers["severity"]
    sev_probs = {int(k): v for k, v in sev["probabilities"].items()}
    sev_level = max(sev_probs, key=sev_probs.get)

    reasons = []
    if URGENT_NO < p_urgent < URGENT_YES:
        reasons.append(f"urgency unclear (p={p_urgent:.2f})")
    if team["confidence"] < MIN_TEAM_CONFIDENCE:
        reasons.append(f"team unclear ({team['choice']}, confidence={team['confidence']:.2f})")
    if team["choice"] == "other":
        reasons.append("no matching team")
    if sev["confidence"] < MIN_SEVERITY_CONFIDENCE:
        reasons.append(f"severity unclear (score={sev['score']:.2f}, confidence={sev['confidence']:.2f})")

    return {
        "id": ticket_id,
        "urgent": p_urgent >= URGENT_YES,
        "team": team["choice"],
        "severity": SEVERITY_LABELS[sev_level],
        "needs_human": bool(reasons),
        "review_reasons": reasons,
        "raw": {
            "p_urgent": p_urgent,
            "team_probabilities": team["probabilities"],
            "team_confidence": team["confidence"],
            "severity_score": sev["score"],
            "severity_probabilities": sev["probabilities"],
            "severity_confidence": sev["confidence"],
        },
    }


def read_tickets(path: str):
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            if path.endswith(".jsonl"):
                obj = json.loads(line)
                yield obj.get("id", n), obj["text"]
            else:
                yield n, line


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help=".jsonl with id/text per line, or plain text with one ticket per line")
    args = parser.parse_args()

    key = os.environ.get("SUBQ_API_KEY")
    if not key:
        print("SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    total = flagged = failed = input_tokens = 0
    for ticket_id, text in read_tickets(args.tickets):
        total += 1
        try:
            result = decide(key, {"ticket": text}, QUESTIONS)
            input_tokens += result.get("usage", {}).get("input_tokens", 0)
            row = triage(ticket_id, text, result["answers"])
        except FatalError as e:
            print(f"stopping: {e}", file=sys.stderr)
            return 1
        except (SnapError, KeyError, TypeError, ValueError) as e:
            # Failed or malformed decision: never guess, send it to a person.
            failed += 1
            row = {"id": ticket_id, "urgent": None, "team": None, "severity": None,
                   "needs_human": True, "review_reasons": [f"triage failed: {e}"]}
        flagged += row["needs_human"]
        print(json.dumps(row), flush=True)

    print(f"{total} tickets, {flagged} flagged for human review ({failed} failed), "
          f"{input_tokens} input tokens (~${input_tokens * 0.05 / 1e6:.4f})", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Triage support tickets with SubQ Snap (subq-snap-preview, POST https://api.subq.ai/v1/systemone).

For each ticket, one request asks three independent questions:
  urgent   (noul)   - does it need a response within the hour?
  team     (choice) - billing / engineering / sales / other
  severity (score)  - low / medium / high
Code then flags uncertain answers for a human.

Input:  JSONL, one ticket per line: {"id": "...", "text": "..."}
Output: JSONL, one result per line (raw probabilities kept so thresholds can be retuned without rerunning).

    export SUBQ_API_KEY=...          # never put the key in this file
    python3 triage.py tickets.jsonl > triaged.jsonl

Standard library only.
"""

from __future__ import annotations

import argparse
import http.client
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Placeholder thresholds. Calibrate them on tickets you have already labelled before trusting them.
URGENT_YES = 0.7          # noul >= this -> urgent
URGENT_NO = 0.3           # noul <= this -> not urgent; anything between goes to a human
TEAM_MIN_CONFIDENCE = 0.6
SEVERITY_MIN_CONFIDENCE = 0.5

TEAMS = ["billing", "engineering", "sales", "other"]
SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Read the support ticket in state.ticket_text. Does it need a response within the hour?",
        "criteria": {
            "true": "Outage, data loss, security incident, customer cannot pay or is being wrongly charged right now, "
                    "or a business-critical workflow is blocked",
            "false": "Questions, feature requests, minor bugs with a workaround, or anything that can wait "
                     "until the next business day",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Read the support ticket in state.ticket_text. Which team should own it?",
        "criteria": {
            "billing": "Charges, invoices, refunds, payment methods, receipts, taxes",
            "engineering": "Bugs, crashes, errors, outages, performance, integrations, API or login problems",
            "sales": "Pricing questions, plans, upgrades, quotes, new purchases, contract renewals",
            "other": None,
        },
    },
    "severity": {
        "type": "score",
        "instructions": "Read the support ticket in state.ticket_text. How badly is the customer affected?",
        "criteria": [
            "Low: a question, a cosmetic issue, or a request with no impact on the customer's work",
            "Medium: something is broken or wrong but the customer has a workaround or only part of the work is affected",
            "High: the customer cannot use the product, is losing money or data, or many users are affected",
        ],
    },
}


class SnapError(Exception):
    def __init__(self, status: int | None, error_type: str, message: str) -> None:
        super().__init__(f"{status} {error_type}: {message}")
        self.status = status
        self.error_type = error_type


class FatalSnapError(SnapError):
    """Errors that will fail for every ticket (bad key, no credits, no model access): stop the run."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # Never follow redirects: urllib would resend the Authorization header to the new location.
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        return None


_OPENER = urllib.request.build_opener(_NoRedirect)


def _error_detail(e: urllib.error.HTTPError) -> dict:
    # SubQ errors look like {"detail": {"error_type": "...", "message": "..."}}.
    try:
        payload = json.load(e)
    except ValueError:
        return {"error_type": "http_error", "message": ""}
    detail = payload.get("detail") if isinstance(payload, dict) else None
    return detail if isinstance(detail, dict) else {"error_type": "http_error", "message": str(payload)[:200]}


def decide(state, questions: dict, *, key: str, attempts: int = 5, timeout_s: float = 60.0,
           base_delay_s: float = 1.0, max_delay_s: float = 30.0) -> dict:
    data = json.dumps({"model": MODEL, "state": state, "questions": questions}).encode()
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    for attempt in range(attempts):
        last = attempt == attempts - 1
        try:
            req = urllib.request.Request(URL, data=data, headers=headers, method="POST")
            with _OPENER.open(req, timeout=timeout_s) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            d = _error_detail(e)
            err_type, msg = d.get("error_type", "http_error"), d.get("message", "")
            if e.code in (401, 402, 403):
                raise FatalSnapError(e.code, err_type, msg) from e
            if not (e.code == 429 or e.code >= 500) or last:
                raise SnapError(e.code, err_type, msg) from e  # 400 / 422 / other 4xx: retrying won't help
        except (OSError, http.client.HTTPException, ValueError) as e:
            # Timeouts, resets, truncated or non-JSON bodies. Retrying is safe: a decision has no side effects.
            if last:
                raise SnapError(None, "network", f"{type(e).__name__}: {e}") from e
        time.sleep(random.uniform(0, min(max_delay_s, base_delay_s * 2 ** attempt)))  # full jitter
    raise SnapError(None, "internal", "retry loop ended without a result")


def _argmax_level(probabilities, n_levels: int) -> int:
    """Index of the most likely score level; accepts a list or a dict keyed by level text/index."""
    if isinstance(probabilities, list):
        probs = probabilities
    else:
        values = list(probabilities.values())
        probs = values if len(values) == n_levels else [0.0] * n_levels
    return max(range(len(probs)), key=lambda i: probs[i])


def interpret(answers: dict) -> dict:
    reasons = []

    p_urgent = float(answers["urgent"]["noul"])
    if p_urgent >= URGENT_YES:
        urgent = True
    elif p_urgent <= URGENT_NO:
        urgent = False
    else:
        urgent = None
        reasons.append(f"urgency unclear (p={p_urgent:.2f})")

    team_ans = answers["team"]
    team, team_conf = team_ans["choice"], float(team_ans["confidence"])
    if team_conf < TEAM_MIN_CONFIDENCE:
        reasons.append(f"team uncertain ({team} at {team_conf:.2f})")
    if team == "other":
        reasons.append("no matching team")

    sev_ans = answers["severity"]
    sev_conf = float(sev_ans["confidence"])
    sev_idx = _argmax_level(sev_ans["probabilities"], len(SEVERITY_LEVELS))
    severity = SEVERITY_LEVELS[sev_idx]
    if sev_conf < SEVERITY_MIN_CONFIDENCE:
        reasons.append(f"severity uncertain ({severity} at {sev_conf:.2f})")

    # A costly mistake: high severity but not confidently urgent deserves a second look.
    if severity == "high" and urgent is False:
        reasons.append("high severity but classified not urgent")

    return {
        "urgent": urgent,
        "team": team,
        "severity": severity,
        "needs_human": bool(reasons),
        "review_reasons": reasons,
        "raw": {
            "urgent_p": p_urgent,
            "team_probabilities": team_ans.get("probabilities"),
            "team_confidence": team_conf,
            "severity_score": sev_ans.get("score"),
            "severity_probabilities": sev_ans.get("probabilities"),
            "severity_confidence": sev_conf,
        },
    }


def triage_ticket(ticket: dict, key: str) -> dict:
    out = {"id": ticket.get("id")}
    text = (ticket.get("text") or "").strip()
    if not text:
        return out | {"needs_human": True, "review_reasons": ["empty ticket"]}
    t0 = time.perf_counter()
    try:
        result = decide({"ticket_text": text}, QUESTIONS, key=key)
    except FatalSnapError:
        raise
    except SnapError as e:
        # Per-ticket failure (e.g. 400 ticket too long, retries exhausted): hand it to a person, keep going.
        return out | {"needs_human": True, "review_reasons": [f"api error: {e}"], "error_status": e.status}
    out |= interpret(result["answers"])
    out["input_tokens"] = result.get("usage", {}).get("input_tokens")
    out["latency_ms"] = round((time.perf_counter() - t0) * 1000)
    return out


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("tickets", help="JSONL file with {\"id\", \"text\"} per line ('-' for stdin)")
    args = ap.parse_args()

    key = os.environ.get("SUBQ_API_KEY")
    if not key:
        print("SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    src = sys.stdin if args.tickets == "-" else open(args.tickets, encoding="utf-8")
    n = flagged = 0
    with src:
        for lineno, line in enumerate(src, 1):
            if not line.strip():
                continue
            try:
                ticket = json.loads(line)
            except ValueError:
                ticket = {"id": f"line-{lineno}", "text": None}
            try:
                res = triage_ticket(ticket, key)
            except FatalSnapError as e:
                print(f"aborting: {e}", file=sys.stderr)
                return 1
            n += 1
            flagged += res["needs_human"]
            print(json.dumps(res), flush=True)
    print(f"{n} tickets, {flagged} flagged for human review", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

