        response = decide(key, {"ticket_text": text}, QUESTIONS)
        result["latency_ms"] = round((time.perf_counter() - t0) * 1000)
        result["input_tokens"] = response.get("usage", {}).get("input_tokens")
        result.update(interpret(response["answers"]))
    except SnapError as e:
        if e.status in (401, 402, 403):
            raise  # bad key, no credits or no model access: every ticket would fail, so stop
        result.update(needs_human=True, review_reasons=[f"API error: {e}"])
    except (KeyError, TypeError) as e:
        result.update(needs_human=True, review_reasons=[f"unexpected response shape: {e!r}"])
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help="JSONL file of {id, text} tickets ('-' for stdin)")
    args = parser.parse_args()

    key = os.environ.get("SUBQ_API_KEY")
    if not key:
        print("SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    src = sys.stdin if args.tickets == "-" else open(args.tickets, encoding="utf-8")
    flagged = total = 0
    with src:
        for lineno, line in enumerate(src, 1):
            if not line.strip():
                continue
            try:
                ticket = json.loads(line)
            except json.JSONDecodeError as e:
                print(f"line {lineno}: invalid JSON ({e}), skipped", file=sys.stderr)
                continue
            ticket.setdefault("id", lineno)
            try:
                result = triage_ticket(key, ticket)
            except SnapError as e:
                print(f"fatal API error, stopping: {e}", file=sys.stderr)
                return 1
            total += 1
            flagged += result["needs_human"]
            print(json.dumps(result), flush=True)

    print(f"{total} tickets triaged, {flagged} flagged for human review", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Triage support tickets with SubQ's Snap decision model.

Input:  JSONL, one ticket per line: {"id": "...", "text": "..."}
Output: JSONL, one result per ticket (stdout or --out).

Usage:
    export SUBQ_API_KEY=...
    python triage.py tickets.jsonl --out triaged.jsonl
"""

import argparse
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

API_URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

TEAMS = ["billing", "engineering", "sales", "other"]
SEVERITY_LEVELS = ["low", "medium", "high"]

# Below these, a human should look at the ticket. Tune on real data;
# the API docs don't formally define how `confidence` is computed.
URGENT_UNSURE_BAND = (0.3, 0.7)  # noul probability in this band -> unsure
MIN_TEAM_CONFIDENCE = 0.6
MIN_SEVERITY_CONFIDENCE = 0.5

RETRYABLE_STATUS = {429, 500, 502, 503, 504}
FATAL_STATUS = {401, 402, 403}  # bad key / no credits / no model access: stop the run
MAX_ATTEMPTS = 5
BASE_DELAY = 1.0
MAX_DELAY = 30.0
TIMEOUT = 30

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Does this support ticket need an urgent response (within hours, not days)?",
        "criteria": {
            "true": "Outage, data loss, security issue, customer blocked from working, "
                    "payment failure affecting service, or explicit hard deadline",
            "false": "General question, feature request, minor bug with a workaround, "
                     "or anything that can wait for normal queue handling",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Which team should own this support ticket?",
        "criteria": {
            "billing": "Invoices, charges, refunds, payment methods, subscription or plan changes",
            "engineering": "Bugs, errors, outages, performance, integrations, API or technical problems",
            "sales": "Pricing inquiries, quotes, upgrades, new purchases, demos, contract negotiation",
            "other": "Anything that does not clearly fit billing, engineering, or sales",
        },
    },
    "severity": {
        "type": "score",
        "instructions": "How severe is the customer's problem in terms of business impact?",
        "criteria": [
            "Low: minor inconvenience, question, or cosmetic issue",
            "Medium: a feature is degraded or a workaround is needed",
            "High: service down, data loss, security exposure, or many users blocked",
        ],
    },
}


class FatalAPIError(Exception):
    """Errors that will not succeed on any ticket (auth, credits, permissions)."""


class TicketError(Exception):
    """Errors specific to one ticket's request (e.g. too long, rejected)."""


def _retry_delay(attempt, retry_after):
    if retry_after:
        try:
            return min(float(retry_after), MAX_DELAY)
        except ValueError:
            pass
    # Exponential backoff with full jitter.
    return random.uniform(0, min(MAX_DELAY, BASE_DELAY * 2 ** attempt))


def call_snap(api_key, text):
    body = json.dumps({"model": MODEL, "state": text, "questions": QUESTIONS}).encode()
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    last_err = None
    for attempt in range(MAX_ATTEMPTS):
        req = urllib.request.Request(API_URL, data=body, headers=headers, method="POST")
        retry_after = None
        try:
            with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            detail = _error_detail(e)
            if e.code in FATAL_STATUS:
                raise FatalAPIError(f"HTTP {e.code}: {detail}") from None
            if e.code not in RETRYABLE_STATUS:
                # 400 (too long / rejected), 422 (invalid request): retrying won't help.
                raise TicketError(f"HTTP {e.code}: {detail}") from None
            last_err = f"HTTP {e.code}: {detail}"
            retry_after = e.headers.get("Retry-After")
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            last_err = f"network error: {e}"

        if attempt < MAX_ATTEMPTS - 1:
            delay = _retry_delay(attempt, retry_after)
            print(f"  retrying in {delay:.1f}s ({last_err})", file=sys.stderr)
            time.sleep(delay)

    raise TicketError(f"gave up after {MAX_ATTEMPTS} attempts: {last_err}")


def _error_detail(err):
    try:
        detail = json.load(err).get("detail", {})
        if isinstance(detail, dict):
            return f"{detail.get('error_type', '')}: {detail.get('message', '')}".strip(": ")
        return str(detail)
    except Exception:
        return err.reason or "unknown error"


def _top_level(probabilities):
    """Return (index, prob) of the most likely severity level.

    Handles probabilities as either a list (in level order) or a dict
    keyed by level label, since the docs don't pin down the score shape.
    """
    if isinstance(probabilities, dict):
        values = list(probabilities.values())
    else:
        values = list(probabilities)
    idx = max(range(len(values)), key=values.__getitem__)
    return idx, values[idx]


def interpret(answers):
    reasons = []

    urgent_p = answers["urgent"]["noul"]
    lo, hi = URGENT_UNSURE_BAND
    if lo <= urgent_p <= hi:
        reasons.append(f"urgency unclear (p={urgent_p:.2f})")

    team = answers["team"]
    if team["confidence"] < MIN_TEAM_CONFIDENCE:
        reasons.append(f"team unclear ({team['choice']}, conf={team['confidence']:.2f})")

    sev = answers["severity"]
    sev_idx, _ = _top_level(sev["probabilities"])
    if sev["confidence"] < MIN_SEVERITY_CONFIDENCE:
        reasons.append(f"severity unclear (conf={sev['confidence']:.2f})")

    return {
        "urgent": urgent_p > 0.5,
        "urgent_probability": round(urgent_p, 3),
        "team": team["choice"],
        "team_confidence": round(team["confidence"], 3),
        "severity": SEVERITY_LEVELS[sev_idx],
        "severity_score": sev["score"],
        "severity_confidence": round(sev["confidence"], 3),
        "needs_human": bool(reasons),
        "review_reasons": reasons,
    }


def triage_ticket(api_key, ticket):
    result = {"id": ticket.get("id")}
    text = (ticket.get("text") or "").strip()
    if not text:
        return {**result, "needs_human": True, "review_reasons": ["empty ticket"]}
    try:
        resp = call_snap(api_key, text)
        result.update(interpret(resp["answers"]))
    except TicketError as e:
        result.update(needs_human=True, review_reasons=[f"API error: {e}"])
    except (KeyError, TypeError, ValueError) as e:
        result.update(needs_human=True, review_reasons=[f"unexpected response shape: {e!r}"])
    return result


def read_tickets(path):
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                ticket = json.loads(line)
            except json.JSONDecodeError as e:
                print(f"skipping line {lineno}: invalid JSON ({e})", file=sys.stderr)
                continue
            ticket.setdefault("id", f"line-{lineno}")
            yield ticket


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help="JSONL file with {id, text} per line")
    parser.add_argument("--out", help="output JSONL path (default: stdout)")
    args = parser.parse_args()

    api_key = os.environ.get("SUBQ_API_KEY")
    if not api_key:
        sys.exit("SUBQ_API_KEY is not set")

    out = open(args.out, "w", encoding="utf-8") if args.out else sys.stdout
    total = flagged = 0
    try:
        for ticket in read_tickets(args.tickets):
            result = triage_ticket(api_key, ticket)
            out.write(json.dumps(result) + "\n")
            out.flush()
            total += 1
            flagged += result["needs_human"]
    except FatalAPIError as e:
        sys.exit(f"aborting after {total} tickets: {e}")
    finally:
        if out is not sys.stdout:
            out.close()

    print(f"triaged {total} tickets, {flagged} flagged for human review", file=sys.stderr)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Triage customer support tickets with SubQ Snap (Decisions API).

Input: a file with one ticket per line. Each line is either a JSON object
({"id": ..., "text": ...}) or plain text (the line number becomes the id).
Output: one JSON object per ticket on stdout (JSONL).

Usage:
    SUBQ_API_KEY=... python triage.py tickets.jsonl > triaged.jsonl
"""

import argparse
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

API_URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

# Thresholds for routing to a human. The docs define no official cut-offs,
# so these are deliberately conservative starting points.
URGENT_BAND = (0.3, 0.7)  # urgency probability inside this band = ambiguous
MIN_CONFIDENCE = 0.6      # choice/score confidence below this = ambiguous

MAX_RETRIES = 5
BASE_BACKOFF = 1.0  # seconds
MAX_BACKOFF = 30.0
TIMEOUT = 60

TEAMS = {
    "billing": "Invoices, charges, refunds, payment methods, plan/pricing questions on an existing account",
    "engineering": "Bugs, outages, errors, performance problems, integrations, API or technical issues",
    "sales": "New purchases, upgrades, quotes, demos, trials, contract or licensing inquiries from prospects",
    "other": "Anything that does not clearly fit billing, engineering, or sales",
}
SEVERITY_LEVELS = [
    "Low: minor inconvenience, question, or cosmetic issue; workaround exists",
    "Medium: meaningful impact on the customer's work but not blocking; partial workaround",
    "High: service down, data loss, security issue, or blocking many users/revenue",
]
SEVERITY_NAMES = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Does this support ticket require an urgent response (within hours, not days)?",
        "criteria": {
            "true": "Outage, blocked work, security or data-loss concern, payment failure stopping service, or explicit time-critical deadline",
            "false": "Routine question, feature request, or issue that can wait for normal queue handling",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Which team should own this support ticket?",
        "criteria": TEAMS,
    },
    "severity": {
        "type": "score",
        "instructions": "How severe is the customer's problem described in this ticket?",
        "criteria": SEVERITY_LEVELS,
    },
}


class FatalAPIError(Exception):
    """Errors that will not go away on retry and affect every ticket (auth, credits, access)."""


class TicketAPIError(Exception):
    """Errors specific to one request (bad/oversized input) or retries exhausted."""


def _error_detail(err: urllib.error.HTTPError) -> str:
    try:
        body = json.loads(err.read().decode("utf-8"))
        detail = body.get("detail", body)
        if isinstance(detail, dict):
            return f"{detail.get('error_type', '')}: {detail.get('message', '')}".strip(": ")
        return str(detail)
    except Exception:
        return err.reason or ""


def _retry_delay(attempt: int, err: urllib.error.HTTPError | None = None) -> float:
    if err is not None:
        retry_after = err.headers.get("Retry-After") if err.headers else None
        if retry_after:
            try:
                return min(float(retry_after), MAX_BACKOFF)
            except ValueError:
                pass
    # Exponential backoff with full jitter.
    return random.uniform(0, min(MAX_BACKOFF, BASE_BACKOFF * 2 ** attempt))


def call_snap(api_key: str, ticket_text: str) -> dict:
    payload = json.dumps({"model": MODEL, "state": ticket_text, "questions": QUESTIONS}).encode("utf-8")
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    for attempt in range(MAX_RETRIES + 1):
        req = urllib.request.Request(API_URL, data=payload, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            detail = _error_detail(e)
            if e.code in (401, 402, 403):
                raise FatalAPIError(f"HTTP {e.code}: {detail}") from e
            if e.code in (400, 422):
                raise TicketAPIError(f"HTTP {e.code}: {detail}") from e
            if e.code == 429 or e.code >= 500:
                if attempt == MAX_RETRIES:
                    raise TicketAPIError(f"HTTP {e.code} after {MAX_RETRIES} retries: {detail}") from e
                delay = _retry_delay(attempt, e)
                print(f"  HTTP {e.code}, retrying in {delay:.1f}s", file=sys.stderr)
                time.sleep(delay)
                continue
            raise TicketAPIError(f"HTTP {e.code}: {detail}") from e
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            if attempt == MAX_RETRIES:
                raise TicketAPIError(f"network error after {MAX_RETRIES} retries: {e}") from e
            delay = _retry_delay(attempt)
            print(f"  network error ({e}), retrying in {delay:.1f}s", file=sys.stderr)
            time.sleep(delay)
        except json.JSONDecodeError as e:
            raise TicketAPIError(f"invalid JSON response: {e}") from e

    raise AssertionError("unreachable")


def interpret(answers: dict) -> dict:
    reasons = []

    p_urgent = float(answers["urgent"]["noul"])
    if URGENT_BAND[0] <= p_urgent <= URGENT_BAND[1]:
        reasons.append(f"urgency ambiguous (p={p_urgent:.2f})")

    team_ans = answers["team"]
    team, team_conf = team_ans["choice"], float(team_ans["confidence"])
    if team_conf < MIN_CONFIDENCE:
        reasons.append(f"team uncertain ({team}, confidence={team_conf:.2f})")

    sev_ans = answers["severity"]
    probs = {int(k): float(v) for k, v in sev_ans["probabilities"].items()}
    sev_idx = max(probs, key=probs.get)
    sev_conf = float(sev_ans["confidence"])
    if sev_conf < MIN_CONFIDENCE:
        reasons.append(f"severity uncertain ({SEVERITY_NAMES[sev_idx]}, confidence={sev_conf:.2f})")

    return {
        "urgent": p_urgent >= 0.5,
        "urgent_probability": round(p_urgent, 3),
        "team": team,
        "team_confidence": round(team_conf, 3),
        "severity": SEVERITY_NAMES[sev_idx],
        "severity_score": round(float(sev_ans["score"]), 3),  # 0..2, probability-weighted
        "severity_confidence": round(sev_conf, 3),
        "needs_human": bool(reasons),
        "review_reasons": reasons,
    }


def load_tickets(path: str):
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
                if isinstance(obj, dict) and "text" in obj:
                    yield obj.get("id", lineno), obj["text"]
                    continue
            except json.JSONDecodeError:
                pass
            yield lineno, line


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help="JSONL ({'id','text'}) or plain text, one ticket per line")
    args = parser.parse_args()

    api_key = os.environ.get("SUBQ_API_KEY")
    if not api_key:
        print("error: SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    n_ok = n_flagged = n_failed = 0
    for ticket_id, text in load_tickets(args.tickets):
        print(f"ticket {ticket_id}...", file=sys.stderr)
        result = {"id": ticket_id}
        try:
            result.update(interpret(call_snap(api_key, text)["answers"]))
            n_ok += 1
            n_flagged += result["needs_human"]
        except FatalAPIError as e:
            print(f"fatal: {e}; stopping", file=sys.stderr)
            return 1
        except (TicketAPIError, KeyError, TypeError, ValueError) as e:
            # Could not get a usable decision: hand the ticket to a human.
            result.update({"needs_human": True, "review_reasons": [f"triage failed: {e}"], "error": str(e)})
            n_failed += 1
        print(json.dumps(result), flush=True)

    print(f"done: {n_ok} triaged ({n_flagged} flagged for review), {n_failed} failed", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Triage customer support tickets with SubQ Snap (Decisions API).

For each ticket, one request asks three questions:
  urgent   (noul)   -> probability the ticket is urgent
  team     (choice) -> billing | engineering | sales | other
  severity (score)  -> low | medium | high

Input: a JSONL file of {"id": ..., "text": ...} objects, or a plain-text
file with one ticket per line. Output: JSONL, one result per ticket.

Usage:
  export SUBQ_API_KEY=...
  python triage.py tickets.jsonl > results.jsonl
"""

import argparse
import json
import os
import random
import sys
import time
import urllib.error
import urllib.request

API_URL = "https://api.subq.ai/v1/systemone"
MODEL = "subq-snap-preview"

MAX_ATTEMPTS = 5
BASE_BACKOFF_S = 1.0
MAX_BACKOFF_S = 30.0
TIMEOUT_S = 60

# Uncertainty thresholds: anything outside these goes to a human.
URGENT_UNSURE_BAND = (0.3, 0.7)  # P(urgent) in this band is ambiguous
MIN_CHOICE_CONFIDENCE = 0.6
MIN_SCORE_CONFIDENCE = 0.6

SEVERITY_LEVELS = ["low", "medium", "high"]

QUESTIONS = {
    "urgent": {
        "type": "noul",
        "instructions": "Does this support ticket need a response within hours rather than days?",
        "criteria": {
            "true": "Service outage, data loss, security issue, blocked payment or "
                    "checkout, customer unable to work, or explicit hard deadline today.",
            "false": "General question, feature request, minor bug with a workaround, "
                     "or anything that can reasonably wait a business day or more.",
        },
    },
    "team": {
        "type": "choice",
        "instructions": "Which team should own this support ticket?",
        "criteria": {
            "billing": "Invoices, charges, refunds, payment methods, subscription or plan changes, pricing disputes.",
            "engineering": "Bugs, errors, outages, performance, integrations, API or technical product problems.",
            "sales": "New purchases, quotes, upgrades for more seats/features, demos, contract or partnership inquiries.",
            "other": "Anything that does not clearly fit billing, engineering, or sales.",
        },
    },
    "severity": {
        "type": "score",
        "instructions": "How severe is the customer's problem in terms of business impact?",
        "criteria": [
            "Low: cosmetic issue, question, or request; little or no impact.",
            "Medium: degraded experience or partial loss of function; workaround exists.",
            "High: critical function unavailable, data loss, security or financial harm; no workaround.",
        ],
    },
}


class FatalAPIError(Exception):
    """Errors that will not succeed for any ticket (auth, credits, model access)."""


class TicketAPIError(Exception):
    """Errors specific to one request (e.g. rejected or invalid input)."""


def _error_message(body: bytes) -> str:
    try:
        detail = json.loads(body).get("detail", {})
        if isinstance(detail, dict):
            return f"{detail.get('error_type')}: {detail.get('message')}"
        return str(detail)
    except (ValueError, AttributeError):
        return body[:500].decode("utf-8", "replace")


def _retry_delay(attempt: int, retry_after: str | None) -> float:
    if retry_after:
        try:
            return min(float(retry_after), MAX_BACKOFF_S)
        except ValueError:
            pass
    # Exponential backoff with full jitter.
    return random.uniform(0, min(MAX_BACKOFF_S, BASE_BACKOFF_S * 2 ** attempt))


def call_snap(api_key: str, ticket_text: str) -> dict:
    payload = json.dumps({"model": MODEL, "state": ticket_text, "questions": QUESTIONS}).encode()
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    last_error = None
    for attempt in range(MAX_ATTEMPTS):
        req = urllib.request.Request(API_URL, data=payload, headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=TIMEOUT_S) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            msg = f"HTTP {e.code} {_error_message(e.read())}"
            if e.code in (401, 402, 403):
                raise FatalAPIError(msg) from e
            if e.code in (400, 422):
                raise TicketAPIError(msg) from e
            if e.code != 429 and e.code < 500:
                raise TicketAPIError(msg) from e
            last_error = msg
            retry_after = e.headers.get("Retry-After") if e.headers else None
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            last_error = f"network error: {e}"
            retry_after = None
        except json.JSONDecodeError as e:
            last_error = f"invalid JSON response: {e}"
            retry_after = None

        if attempt < MAX_ATTEMPTS - 1:
            delay = _retry_delay(attempt, retry_after)
            print(f"  retrying in {delay:.1f}s after {last_error}", file=sys.stderr)
            time.sleep(delay)

    raise TicketAPIError(f"gave up after {MAX_ATTEMPTS} attempts: {last_error}")


def interpret(answers: dict) -> dict:
    reasons = []

    p_urgent = answers["urgent"]["noul"]
    urgent = p_urgent >= 0.5
    lo, hi = URGENT_UNSURE_BAND
    if lo < p_urgent < hi:
        reasons.append(f"urgency ambiguous (p={p_urgent:.2f})")

    team_ans = answers["team"]
    team = team_ans["choice"]
    if team_ans["confidence"] < MIN_CHOICE_CONFIDENCE:
        reasons.append(f"team uncertain (confidence={team_ans['confidence']:.2f})")
    if team == "other":
        reasons.append("no clear owning team")

    sev_ans = answers["severity"]
    # score is probability-weighted over levels 0..2 and may fall between them.
    sev_score = sev_ans["score"]
    sev_idx = max(0, min(len(SEVERITY_LEVELS) - 1, round(sev_score)))
    if sev_ans["confidence"] < MIN_SCORE_CONFIDENCE:
        reasons.append(f"severity uncertain (confidence={sev_ans['confidence']:.2f})")

    # A high-severity ticket judged non-urgent (or vice versa) is worth a look.
    if sev_idx == 2 and not urgent:
        reasons.append("high severity but not urgent")

    return {
        "urgent": urgent,
        "urgent_probability": round(p_urgent, 3),
        "team": team,
        "team_confidence": round(team_ans["confidence"], 3),
        "severity": SEVERITY_LEVELS[sev_idx],
        "severity_score": round(sev_score, 3),
        "severity_confidence": round(sev_ans["confidence"], 3),
        "needs_human": bool(reasons),
        "human_review_reasons": reasons,
    }


def load_tickets(path: str):
    with open(path, encoding="utf-8") as f:
        for i, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                obj = None
            if isinstance(obj, dict) and "text" in obj:
                yield obj.get("id", i), obj["text"]
            else:
                yield i, line


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("tickets", help="JSONL ({id, text}) or plain text, one ticket per line")
    args = parser.parse_args()

    api_key = os.environ.get("SUBQ_API_KEY")
    if not api_key:
        print("error: SUBQ_API_KEY is not set", file=sys.stderr)
        return 2

    failures = 0
    for ticket_id, text in load_tickets(args.tickets):
        print(f"ticket {ticket_id}", file=sys.stderr)
        result = {"id": ticket_id}
        try:
            result.update(interpret(call_snap(api_key, text)["answers"]))
        except FatalAPIError as e:
            print(f"fatal API error, stopping: {e}", file=sys.stderr)
            return 1
        except TicketAPIError as e:
            failures += 1
            result.update({"needs_human": True, "human_review_reasons": [f"API error: {e}"]})
        except (KeyError, TypeError) as e:
            failures += 1
            result.update({"needs_human": True, "human_review_reasons": [f"unexpected response shape: {e!r}"]})
        print(json.dumps(result), flush=True)

    if failures:
        print(f"{failures} ticket(s) failed and were flagged for human review", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
